// Package messages holds the C# app's texts (XenModel/Messages.resx and FriendlyNames.resx), generated by
// tools/resx2go, so the Go app says exactly what the Windows app says. Add a prefix below and run go generate.
package messages

import (
	"fmt"
	"strconv"
	"strings"
)

//go:generate go run ../../tools/resx2go -o messages_gen.go -var texts -prefix ALERT_,CONFIRM_,HA_CONFIRM_,MAINWINDOW_TOOLBAR_,STRING_COLON_SPACE_STRING,SHUT_DOWN_POOL_COORDINATOR_SINGLE,HA_CANNOT_EVACUATE_COORDINATOR,EVACUATE_HOST_DIALOG_TITLE,ENTER_MAINTENANCE_MODE,EXIT_MAINTENANCE_MODE,SNAPSHOT_REVERT_,REMOVE_SNAPSHOT_TEXT,THE_SNAPSHOT,SNAPSHOTS_EMPTY,DISKS_AND_MEMORY,DISKS_ONLY,INFO_DISKMEMORY_MODE_,STORAGE_WORST,STORAGE_BEST,IN_POOL,ON_SERVER,NEW_DVD_DRIVE_REBOOT,MESSAGEBOX_DETACH_,MESSAGEBOX_DELETE_VD,MESSAGEBOX_DELETE_SYS_DISK,DEFAULT_VDI_NAME,NEWVM_DEFAULTNAME,NEWDISKWIZARD_MESSAGE,CANNOT_DELETE_VDI_ACTIVE_ON,CPU_TOPOLOGY_,VM_CPUMEMPAGE_,VCPU_ONLY_WHEN_HALTED,VM_VCPU_CANNOT_UNPLUG_LIVE,GRAPHS_DEFAULT_NAME_,NEWVMWIZARD_STORAGEPAGE_DISK_DESCRIPTION,NO_MORE_USERDEVICES ../../../XenModel/Messages.resx
//go:generate go run ../../tools/resx2go -o friendly_gen.go -var friendly -prefix Message.name-,Message.body-,Label-performance. ../../../XenModel/FriendlyNames.resx

// Get is a Messages.resx text ("" when the key is not generated).
func Get(key string) string { return texts[key] }

// Friendly is a FriendlyNames.resx text ("" when missing), as FriendlyNameManager.GetFriendlyName.
func Friendly(key string) string { return friendly[key] }

// Format is string.Format for the {0}, {1}... placeholders of these texts.
func Format(format string, args ...any) string {
	pairs := make([]string, 0, 2*len(args))
	for i, a := range args {
		pairs = append(pairs, "{"+strconv.Itoa(i)+"}", fmt.Sprint(a))
	}
	return strings.NewReplacer(pairs...).Replace(format) // one pass: an argument's own "{1}" stays as it is
}
